\begin{tikzpicture}
\begin{axis}[
    width=0.68\textwidth,
    height=0.45\textwidth,
    xmin=-1.1, xmax=3,
    ymin=-0.3, ymax=4.3,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={1},
    ytick={2},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-1:3, samples=2] {x+1};
\addplot[only marks, mark=o, mark size=3pt, thick] coordinates {(1,2)};
\node[anchor=west] at (axis cs:0.95,1.8) {missing point};
\node[anchor=west] at (axis cs:1.55,3.45) {\(y=x+1\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.68\textwidth,
    height=0.48\textwidth,
    xmin=-0.25, xmax=1.5,
    ymin=-0.8, ymax=16,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xlabel style={at={(axis cs:1.5,0)}, anchor=north, yshift=-5pt},
    ylabel style={at={(axis cs:0,16)}, anchor=east, xshift=-3pt},
    xtick={1},
    ytick={1,9},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-0.25:1.5, samples=120] {(2*x+1)^2};
\addplot[only marks, mark=o, mark size=3pt, thick] coordinates {(1,9)};
\addplot[only marks, mark=*, mark size=2.5pt] coordinates {(1,1)};
\node[anchor=west, fill=white, inner sep=1.5pt] at (axis cs:1,9) {nearby height \(9\)};
\node[anchor=west] at (axis cs:1,1) {actual value \(1\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.88\textwidth,
    xmin=-2, xmax=2,
    ymin=-0.45, ymax=1.55,
    axis lines=middle,
    xtick={0},
    ytick={0,1},
    title={outer function not continuous at \(0\)},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-2:-0.06, samples=2] {1};
\addplot[thick, domain=0.06:2, samples=2] {1};
\addplot[only marks, mark=o, mark size=2.8pt, thick] coordinates {(0,1)};
\addplot[only marks, mark=*, mark size=2.5pt] coordinates {(0,0)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
